    { "role": "user", "content": "What is the exchange rate from EUR to JPY right now?" }
  ],
  "tools": [
    { "type": "function", "function": { "name": "get_exchange_rate", "description": "...", "parameters": {...} } },
    { "type": "function", "function": { "name": "get_current_weather", "description": "...", "parameters": {...} } }
  ]
}
```

